import{D as t}from"./chunks/DemoVideo.Cxll-bB3.js";import{o as d,c as s,a2 as a,E as n}from"./chunks/framework.2Gs1zKBA.js";const p=JSON.parse('{"title":"示教与轨迹回放","description":"","frontmatter":{},"headers":[],"relativePath":"use-cases/teaching.md","filePath":"use-cases/teaching.md","lastUpdated":1793694501000}'),i={name:"use-cases/teaching.md"},h=Object.assign(i,{setup(l){return(r,e)=>(d(),s("div",null,[e[0]||(e[0]=a(`<h1 id="示教与轨迹回放" tabindex="-1">示教与轨迹回放 <a class="header-anchor" href="#示教与轨迹回放" aria-label="Permalink to &quot;示教与轨迹回放&quot;">​</a></h1><p>本案例使用 <code>freedrive_enable()</code> 进入重力补偿示教模式，在操作者手动引导机械臂的同时记录关节轨迹，随后以不同速度回放，并验证轨迹保存与重新加载。</p><div class="danger custom-block"><p class="custom-block-title">真机操作提示</p><p>示教模式会使能机械臂并持续输出补偿力矩，不是失能或紧急停止。运行前必须确认基座、安装方向、工具、负载和重心配置正确，清空工作空间并安排操作者随时准备停止设备。退出或失能前必须可靠支撑机械臂，防止机械臂和负载因重力下落。</p></div><h2 id="演示目标" tabindex="-1">演示目标 <a class="header-anchor" href="#演示目标" aria-label="Permalink to &quot;演示目标&quot;">​</a></h2><p>示例依次完成以下流程：</p><ol><li>使能机械臂并开始记录关节状态；</li><li>调用 <code>freedrive_enable()</code> 进入重力补偿示教模式；</li><li>在 10 秒内由操作者手动引导机械臂形成一段轨迹；</li><li>退出示教并停止记录；</li><li>依次以原速、<code>2×</code> 和 <code>0.5×</code> 回放记录；</li><li>将轨迹保存为 <code>my_trajectory.json</code>，再从文件重新加载并回放；</li><li>无论正常结束还是发生异常，最终都会失能机械臂。</li></ol><p>回放只是复现记录的关节轨迹，不会重新规划路径或自动避障。视频和终端信息可以用于确认示教、保存与回放流程，但不能作为轨迹精度、负载能力或碰撞安全的测试结果。</p><h2 id="安装与准备" tabindex="-1">安装与准备 <a class="header-anchor" href="#安装与准备" aria-label="Permalink to &quot;安装与准备&quot;">​</a></h2><p>进入 <code>onero-sdk</code> 仓库并安装动力学依赖：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/workspace/onero-sdk</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.[dynamics]&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>真机运行前还需要完成 <a href="/onerobot-A1/getting-started/hardware">CAN 接口配置与连接检查</a>。示例固定使用 A1R 和 <code>can0</code>，如果型号或 CAN 通道不同，必须先修改源码中的 <code>Arm(...)</code> 参数。</p><p>运行前应完成以下检查：</p><ul><li>已正确配置机械臂型号、CAN 通道和 <code>mounting</code>。</li><li>已测量并设置工具与工件的总质量和合成重心。</li><li>已安装 <code>onero-sdk[dynamics]</code>，且机械臂静止时不会明显下坠、上浮或持续抖动。</li><li>已检查手动引导和全部回放的完整路径，不只检查起点和终点。</li><li>操作者双手、衣物和线缆不会进入关节夹点，现场能够随时停止运动或切断供电。</li></ul><p>示例本身没有显式传入 <code>mounting</code> 或调用 <code>set_payload()</code>。只有默认安装方向和默认负载配置与真机一致时才能直接运行；安装方向、工具或负载不一致时，应先在源码中配置正确参数。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p>本示例没有命令行参数，以下参数固定在源码中：</p><table tabindex="0"><thead><tr><th>参数或设置</th><th>示例值</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>A1R</code></td><td>机械臂型号</td></tr><tr><td><code>channel</code></td><td><code>can0</code></td><td>真机 SocketCAN 通道</td></tr><tr><td><code>damping</code></td><td><code>0.5</code></td><td>示教模式的关节阻尼；数值越大，手动引导阻力通常越明显</td></tr><tr><td>记录时间</td><td><code>10.0 s</code></td><td>进入示教模式后的固定记录窗口</td></tr><tr><td>第一次回放</td><td>默认原速</td><td>按原始记录速度回放</td></tr><tr><td>第二次回放</td><td><code>speed_factor=2.0</code></td><td>以两倍速度回放，不会重新规划轨迹</td></tr><tr><td>第三次回放</td><td><code>speed_factor=0.5</code></td><td>以半速回放</td></tr><tr><td>保存文件</td><td><code>my_trajectory.json</code></td><td>保存后由 <code>Recording.load()</code> 重新读取</td></tr></tbody></table><p>首次真机验证不应直接使用 <code>2×</code> 回放。应先把 <code>speed_factor</code> 调低至 <code>0.5</code>，确认轨迹起点、扫掠空间、关节限位和负载状态安全后，再逐步提高速度。</p><h2 id="操作阶段" tabindex="-1">操作阶段 <a class="header-anchor" href="#操作阶段" aria-label="Permalink to &quot;操作阶段&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">顺序</th><th>接口或终端阶段</th><th>操作含义</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><code>start_recording()</code></td><td>开始记录关节轨迹</td></tr><tr><td style="text-align:right;">2</td><td><code>freedrive_enable()</code></td><td>进入重力补偿示教模式，由操作者手动引导</td></tr><tr><td style="text-align:right;">3</td><td><code>freedrive_disable()</code></td><td>退出示教模式，机械臂仍保持使能</td></tr><tr><td style="text-align:right;">4</td><td><code>stop_recording()</code></td><td>结束记录并生成轨迹对象</td></tr><tr><td style="text-align:right;">5</td><td><code>replay(recording)</code></td><td>按原始速度回放</td></tr><tr><td style="text-align:right;">6</td><td><code>replay(..., 2.0)</code></td><td>以两倍速度回放</td></tr><tr><td style="text-align:right;">7</td><td><code>replay(..., 0.5)</code></td><td>以半速回放</td></tr><tr><td style="text-align:right;">8</td><td><code>recording.save()</code></td><td>保存为 <code>my_trajectory.json</code></td></tr><tr><td style="text-align:right;">9</td><td><code>Recording.load()</code></td><td>从文件重新加载轨迹并再次回放</td></tr><tr><td style="text-align:right;">10</td><td><code>disable()</code></td><td>撤销电机保持力矩</td></tr></tbody></table><p>开始前还应逐项确认：</p><ol><li>先在无附加工具或较轻负载下验证安装方向和重力补偿方向。</li><li>确认当前位置远离关节限位、奇异位形和环境障碍物。</li><li>预留回放空间；回放会复现记录的关节轨迹，不会重新规划或自动避障。</li><li>确认保存路径可写，避免覆盖仍需保留的轨迹文件。</li></ol><h2 id="真机运行" tabindex="-1">真机运行 <a class="header-anchor" href="#真机运行" aria-label="Permalink to &quot;真机运行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/13_teach_replay.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>程序启动后，在 10 秒记录窗口内平稳拖动机械臂。不要突然释放负载或用力冲击关节；轨迹完成后离开工作空间，观察原速、2 倍速、0.5 倍速和重新加载后的回放。</p><p>终端依次输出示教状态、记录结果、三种速度回放和文件加载状态：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进入示教模式 — 请手动引导机械臂...</span></span>
<span class="line"><span>(10 秒后自动退出)</span></span>
<span class="line"><span>录制完成! 共 &lt;帧数&gt; 帧, 时长 10.0 秒</span></span>
<span class="line"><span>回放轨迹 (原速)...</span></span>
<span class="line"><span>回放完成!</span></span>
<span class="line"><span>2 倍速回放...</span></span>
<span class="line"><span>完成!</span></span>
<span class="line"><span>0.5 倍速（慢动作）...</span></span>
<span class="line"><span>完成!</span></span>
<span class="line"><span>轨迹已保存到 my_trajectory.json</span></span>
<span class="line"><span>从文件加载: &lt;帧数&gt; 帧</span></span>
<span class="line"><span>加载并回放完成!</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p><code>&lt;帧数&gt;</code> 由控制频率和实际记录过程决定。程序没有输出“已失能”，但 <code>finally</code> 中会调用 <code>disable()</code>；失能前必须可靠支撑机械臂及负载。</p><h2 id="演示视频" tabindex="-1">演示视频 <a class="header-anchor" href="#演示视频" aria-label="Permalink to &quot;演示视频&quot;">​</a></h2>`,29)),n(t,{src:"/videos/cases/03_freedrive.mp4",title:"示教与回放示例"}),e[1]||(e[1]=a('<h2 id="结果判断" tabindex="-1">结果判断 <a class="header-anchor" href="#结果判断" aria-label="Permalink to &quot;结果判断&quot;">​</a></h2><p>运行成功应同时满足：</p><ul><li>示教阶段能够以适中阻尼平稳引导，没有持续下坠、上浮或振荡；</li><li>记录时长接近 10 秒，记录帧数大于 1；</li><li>当前目录生成 <code>my_trajectory.json</code>，文件内容可以正常读取；</li><li>原速回放连续复现示教轨迹，没有突然跳向错误起点；</li><li><code>2×</code> 回放仍满足关节限位、速度、负载和环境安全要求；</li><li><code>0.5×</code> 回放连续完成，保存文件能够重新加载并回放；</li><li>最后一次回放结束后，机械臂得到可靠支撑并正常失能。</li></ul><p>如果机械臂在示教阶段明显下坠、上浮、振荡，或者回放时突然换位，应立即停止操作，优先检查安装方向、负载参数、轨迹起点和回放速度。不要通过继续减小阻尼或提高回放倍速绕过异常。</p><h2 id="中断与安全状态" tabindex="-1">中断与安全状态 <a class="header-anchor" href="#中断与安全状态" aria-label="Permalink to &quot;中断与安全状态&quot;">​</a></h2><ul><li><code>damping</code> 越大，手动引导阻力通常越明显；不能通过盲目减小阻尼掩盖负载或安装方向错误。</li><li><code>speed_factor</code> 会改变回放速度，不会重新规划轨迹；提高倍速前必须重新评估速度、跟踪误差和碰撞风险。</li><li>环境、工具、负载或安装位置变化后，应重新验证或重新录制轨迹。</li></ul><p>按 <code>Ctrl+C</code> 会中断程序并进入 <code>finally</code>，随后调用 <code>disable()</code>。这不是 <code>emergency_stop()</code>，也不是普通的“停止运动”；失能会撤销保持力矩，因此按键前后都必须支撑机械臂及负载。若现场出现碰撞风险、失控趋势或人员危险，应使用设备的紧急停止措施。</p><p>终端退出、通信关闭和 <code>freedrive_disable()</code> 都不等于失能：<code>freedrive_disable()</code> 只退出示教并恢复位置保持，<code>disable()</code> 才会撤销电机保持力矩。</p><p>详细接口、录制格式和异常退出说明见<a href="/onerobot-A1/advanced/#拖动示教与回放">示教、力控与标定</a>。</p><p><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/13_teach_replay.py" target="_blank" rel="noreferrer">查看源码</a></p>',10))]))}});export{p as __pageData,h as default};
